import assert from 'node:assert/strict';import {readFile,mkdir} from 'node:fs/promises';import {createServer} from 'node:http';import {chromium} from 'playwright';
const paths=[...(await readFile('dist/sitemap.xml','utf8')).matchAll(/<loc>https:\/\/raahhi\.com([^<]*)<\/loc>/g)].map(x=>x[1]);assert.equal(paths.length,270);const titles=new Set(),descs=new Set();let guidance=0;
for(const path of paths){const html=await readFile('dist'+path+'index.html','utf8'),title=html.match(/<title[^>]*>([^<]*)<\/title>/)?.[1],description=html.match(/<meta[^>]*name="description"[^>]*content="([^"]*)"/)?.[1];assert(title&&!titles.has(title),'Unique title '+path);titles.add(title);assert(description&&!descs.has(description),'Unique description '+path);descs.add(description);assert(description.length>=50&&description.length<=160,'Concise description '+path);assert(!/<img\b(?=[^>]*\balt="")(?!(?:[^>]*\brole="presentation"))[^>]*>/i.test(html),'Only explicitly decorative images may have empty alt '+path);assert.equal((html.match(/<h1(?:\s|>)/g)||[]).length,1);const graph=JSON.parse(html.match(/<script[^>]*type="application\/ld\+json"[^>]*>(.*?)<\/script>/s)[1])['@graph'],org=graph.find(n=>n['@type']==='Organization');assert.equal(org.legalName,'Raahi Tourism PVT LTD');assert.equal(org.email,'inquire@raahhi.com');assert.equal(org.telephone,'+91 7678572029');assert.equal(org.address.postalCode,'411045');assert(org.contactPoint.description.includes('India Standard Time'));assert(!/\[BUSINESS[^\]]*TO BE CONFIRMED\]|sister company/i.test(html),'No public placeholders '+path);if(html.includes('class="detail-section verified-visa-guidance"'))guidance++;}assert.equal(guidance,8);
const server=createServer(async(req,res)=>{const p=new URL(req.url,'http://local').pathname;try{res.setHeader('Content-Type',p.endsWith('.js')?'text/javascript':p.endsWith('.css')?'text/css':p.endsWith('.svg')?'image/svg+xml':'text/html');res.end(await readFile('dist'+(p.endsWith('/')?p+'index.html':p)));}catch{res.statusCode=404;res.end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port,browser=await chromium.launch();
try{const p=await browser.newPage({viewport:{width:390,height:900}}),errors=[],outbound=[];p.on('pageerror',e=>errors.push(e.message));await p.route('**/*',r=>r.request().url().startsWith(base)?r.continue():(outbound.push(r.request().url()),r.abort()));const open=async route=>{await p.goto(base+route);await p.waitForFunction(()=>!document.querySelector('[data-currency-select]').disabled);};
await open('/activities/dubai/evening-desert-safari/');const picker=p.locator('[data-product-option]'),id=await picker.locator('option').last().getAttribute('value');await picker.selectOption(id);assert.equal(await p.evaluate(()=>JSON.parse(document.querySelector('script[type="application/ld+json"]').textContent)['@graph'].filter(n=>n.offers).length),0,'No stale Offer after selecting reference');await picker.selectOption('');assert(await p.evaluate(()=>JSON.parse(document.querySelector('script[type="application/ld+json"]').textContent)['@graph'].some(n=>n.offers)));await picker.selectOption(id);await p.locator('#tourEnqGuests').fill('4');await p.evaluate(()=>enquireAboutProduct('activity','evening-desert-safari'));await p.locator('#callbackName').fill('Readiness Test');await p.locator('#callbackPhone').fill('+919876543210');await p.locator('#callbackSubmit').click();const messages=await p.evaluate(()=>[...document.querySelectorAll('[data-enquiry-actions="callbackSummary"] [data-enquiry-channel]')].map(a=>{prepareEnquiryLink(a,'callbackSummary',a.dataset.enquiryChannel);return a.href;}));assert.equal(messages.length,2);const wa=new URL(messages[0]),text=wa.searchParams.get('text');assert.equal(wa.origin+wa.pathname,'https://wa.me/917678572029');assert(text.includes('Readiness Test')&&text.includes('Guests: 4')&&text.includes('Premium Desert Safari')&&text.includes('https://raahhi.com/activities/dubai/evening-desert-safari/'));assert.equal(new URL(messages[1]).pathname,'inquire@raahhi.com');
await open('/contact/');for(const [id,value] of [['contactName','Contact Test'],['contactEmail','test@example.com'],['contactPhone','+919876543210'],['contactMessage','Family enquiry <script>literal</script>']])await p.locator('#'+id).fill(value);await p.locator('#contactPageForm button').click();assert(await p.locator('#contactPageDone').isVisible());assert.equal(await p.locator('#contactMessagePreview script').count(),0);assert.equal(await p.locator('[data-enquiry-actions="contactMessagePreview"] [data-enquiry-channel]').count(),2);
await open('/visas/singapore/');await p.evaluate(()=>openVisaEnquiry('singapore'));for(const [id,value] of [['visaEnqName','Visa Test'],['visaEnqEmail','test@example.com'],['visaEnqPhone','+919876543210']])await p.locator('#'+id).fill(value);for(const [id,value] of [['visaEnqNationality','IN'],['visaEnqResidence','AE'],['visaEnqPurpose','tourism']])await p.locator('#'+id).selectOption(value);await p.locator('#visaEnqForm button[type="submit"]').click();assert.equal(await p.locator('[data-enquiry-actions="visaEnqSummary"] [data-enquiry-channel]').count(),2);
await open('/compare/dubai-observation-decks/');const compared=await p.locator('.comparison-notes[data-product-id="sky-views-observatory"] [data-cancellation-for]').textContent();await open('/activities/dubai/sky-views-observatory/');assert.equal(await p.locator('.page.active [data-cancellation-for]').first().textContent(),compared);await open('/guides/dubai-landmarks/');const rows=await p.locator('table tr').allTextContents();assert(rows.find(t=>t.includes('Dubai Garden Glow')).includes('Outdoor experience'));assert(rows.find(t=>t.includes('Dubai Balloon')).includes('Outdoor experience'));
for(const width of [320,390,768,1440]){await p.setViewportSize({width,height:900});for(const route of ['/contact/','/terms/','/privacy/','/visas/schengen-area/','/guides/dubai-first-visit-planning/','/guides/dubai-family-planning/']){await open(route);assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'No overflow '+width+' '+route);}}
if(process.env.RAAHHI_READINESS_SHOTS){const dir=process.env.RAAHHI_READINESS_SHOTS;await mkdir(dir,{recursive:true});await p.setViewportSize({width:390,height:900});await open('/contact/');await p.screenshot({path:dir+'/contact-mobile.png',fullPage:true});await open('/visas/schengen-area/');await p.locator('.verified-visa-guidance').screenshot({path:dir+'/visa-guidance-mobile.png'});await p.setViewportSize({width:1440,height:1000});await open('/guides/dubai-first-visit-planning/');await p.screenshot({path:dir+'/planning-desktop.png'});}
assert.equal(errors.length,0,errors.join('\n'));assert(!outbound.some(u=>u.includes('wa.me')||u.startsWith('mailto:')));console.log('PASS 270 page identities and metadata; 8 scoped visa guides; policy parity; option Offer consistency; human WhatsApp/email handoffs, escaping and responsive layouts');}finally{await browser.close();server.close();}
